EXTRAS=json.loads(r'''{"samsung":[["اگر نمایشگر عدد درست نشان دهد","برای بررسی نوسان دما، عدد تنظیمی روی پنل را با دمای واقعی قفسه‌ها اشتباه نگیرید. در زمان پرکردن کابین یا پس از باز شدن طولانی در، رسیدن به دمای مطلوب با تأخیر اتفاق می‌افتد. ثبت زمان و وضعیت مواد غذایی به تشخیص کمک می‌کند."],["نشانه‌های محدودشدن مسیر هوا","کاهش سرمای یخچال همراه با سرمای مناسب فریزر می‌تواند حاصل اختلال فن یا بسته شدن مسیر انتقال هوا باشد. اگر صدای فن هنگام بسته بودن در شنیده نمی‌شود، به‌جای بازکردن پنل، شرایط کار دستگاه و مدل دقیق را ثبت کنید تا بررسی ایمن انجام شود."],["تشخیص برد دیجیتال بدون تعویض شتاب‌زده","به محض ظهور کد خطا به خرید برد نروید. شماره مدل و کد را همراه با شرایط بروز ثبت کنید. تکنسین می‌تواند سلامت سنسورها و اتصالات را قبل از تصمیم درباره برد کنترل بررسی کند؛ عوض کردن قطعه صرفاً بر پایه یک علامت قابل اتکا نیست."],["بررسی تغییر دما پس از قطعی برق","پس از قطعی برق طولانی، دمای کابین ممکن است برای مدتی از حالت مطلوب خارج باشد. پیش از قضاوت، مطابق دستور سازنده فرصت پایدار شدن بدهید و وضعیت بسته شدن در را کنترل کنید. اگر افت سرمایش ادامه پیدا کرد، آزمایش فنی ضرورت دارد."]],"lg":[["دو محفظه، دو نشانه متفاوت","در ال‌جی، خوب منجمد شدن فریزر لزوماً به معنی سالم بودن گردش هوای یخچال نیست. در گزارش خرابی به تعمیرکار مشخص کنید کدام محفظه گرم شده و آیا فن داخلی صدای متفاوتی دارد. این تفکیک، آزمون قطعات را هدفمند می‌کند."],["برداشت اشتباه از صدای موتور","کمپرسورهای دارای کنترل دور ممکن است در ساعت‌های مختلف صدای یکنواخت نداشته باشند. همراه با صدا، تغییر دمای واقعی و میزان بازماندن در را بررسی کنید. آزمایش مدار سرمایشی با تجهیزات حرفه‌ای، تشخیص عیب واقعی را ممکن می‌کند."],["چه زمانی بحث مبرد مطرح می‌شود؟","وقتی کاهش سرمایش ادامه‌دار است، صرف شنیدن صدای موتور نمی‌توان گفت گاز کم شده. متخصص باید شرایط کارکرد، عملکرد فن و شواهد احتمالی نشتی را بررسی کند. شارژ بی‌دلیل می‌تواند هم مشکل را پنهان کند و هم هزینه اضافه داشته باشد."],["تهویه و بارگذاری در مصرف روزانه","چسباندن ظروف بزرگ به خروجی هوا یا پرکردن ناگهانی کابین با مواد گرم، آزمون سرمایش را گمراه می‌کند. برای قضاوت درباره سلامت دستگاه شرایط بارگذاری معمول را در نظر بگیرید و پس از تغییر چیدمان، نتیجه را در مدت کافی ثبت کنید."]],"bosch":[["تفاوت هشدار دما و بازماندن در","وقتی آلارم بوش شنیده می‌شود، نخست مشخص کنید دستگاه بابت بازماندن در هشدار می‌دهد یا دمای محفظه افزایش یافته است. هر دو علامت شبیه هم احساس می‌شوند ولی بررسی‌های متفاوتی دارند. عکس نمایشگر و زمان آغاز هشدار را ثبت کنید."],["بررسی مانع فیزیکی درب","بیرون‌زدگی یک کشو یا ظرف در قفسه در، می‌تواند اجازه ندهد لاستیک در دور تا دور کابین تماس پیدا کند. قبل از مراجعه به تعمیرکار با فشار اضافه در را نبندید؛ وضعیت تراز دستگاه و مانع قابل مشاهده را بررسی کنید."],["چرا آلارم پس از ریست برمی‌گردد؟","خاموش و روشن کردن ممکن است صدای هشدار را موقتاً قطع کند، اما ریشه مشکل همچنان وجود داشته باشد. اگر افزایش واقعی دما ادامه داشته باشد باید سنسور، وضعیت در و گردش هوا را به ترتیب مناسب آزمایش کرد. ثبت علامت قبل از ریست بسیار مهم است."],["تصمیم درباره سنسور یا برد","تفسیر هشدارها در سری‌های مختلف بوش به شماره مدل وابسته است. تکنسین باید روش تشخیص همان مدل را دنبال کند و از سفارش برد تنها با استناد به یک آلارم بپرهیزد. نتیجه آزمون باید برای صاحب دستگاه توضیح داده شود."]],"daewoo":[["تشخیص نوع آب‌رسانی در دوو","آب‌ریز همه یخچال‌های دوو یک ساختار ندارد. ممکن است منبع آب یک مخزن قابل برداشتن باشد یا دستگاه به شیر آب ساختمان متصل شود. قبل از بررسی فشار یا فیلتر، نوع سیستم را از دفترچه و شماره مدل مشخص کنید."],["آب کم می‌آید اما موتور سالم است","ضعف جریان آب به‌تنهایی خرابی کمپرسور یا برد اصلی نیست. وضعیت شیر تغذیه، فیلتر و مسیر شلنگ در دستگاه‌های متصل به آب شهری می‌تواند بر آب‌ریز اثر بگذارد. قطعات آب‌رسانی باید با شرایط واقعی دستگاه سنجیده شوند."],["اگر کف آشپزخانه خیس شد","جای رطوبت را بدون لمس قسمت‌های برقی ثبت کنید: زیر بدنه، کنار اتصال آب یا پایین در. نشتی فعال را نباید با استفاده بیشتر آزمایش کرد. در صورت امکان ایمن شیر ورودی را ببندید و برای پیدا کردن محل نشت درخواست سرویس کنید."],["بعد از تعویض فیلتر چه چیزی مهم است؟","فیلتر غیراستاندارد یا اتصال درست جا نخورده می‌تواند کاهش فشار یا چکه ایجاد کند. باید قطعه سازگار با مدل انتخاب و پس از نصب وضعیت تمام اتصالات بررسی شود. درباره زمان تعویض، راهنمای سازنده را ملاک بگذارید."]],"snowa":[["وقتی فریزر سرد و یخچال گرم است","اگر بخش فریزر اسنوا هنوز مواد را منجمد می‌کند ولی طبقات یخچال گرم شده‌اند، ابتدا باید مسیر رساندن هوای سرد را در نظر گرفت. در بعضی حالت‌ها برفک مخفی مانع جریان می‌شود. این الگو با خرابی کامل کمپرسور یکسان نیست."],["صدای تماس فن با یخ","صدای ساییدگی نزدیک پنل داخلی همراه با افت سرما می‌تواند به مشکل فن یا یخ‌زدگی اطراف آن مربوط باشد. از باز کردن پوشش فریزر در حالت برق‌دار خودداری کنید. مدت و شرایط ایجاد صدا را یادداشت کنید تا تکنسین علت را بررسی کند."],["چرا یخ‌زدایی موقتاً جواب می‌دهد؟","آب شدن یخ گاهی مسیر هوا را برای مدت کوتاهی آزاد می‌کند، اما اگر قطعه مسئول یخ‌زدایی درست کار نکند، مشکل بازمی‌گردد. زمان تکرار علامت پس از بازگشت سرمایش می‌تواند اطلاعات مهمی برای عیب‌یابی تخصصی باشد."],["بررسی سامانه دیفراست در سرویس","حسگر دیفراست، هیتر و اجزای حفاظتی باید مطابق مدل و با تست فنی ارزیابی شوند. تعویض همه این قطعات بدون مشخص کردن بخش معیوب کار اصولی نیست. کنترل بسته شدن در فریزر نیز برای جلوگیری از ورود رطوبت مهم است."]],"emersun":[["رد رطوبت دور قاب در","لکه‌های آب نزدیک لبه در امرسان به بررسی ورود هوای مرطوب نیاز دارند. هر لکه‌ای به معنی پاره شدن لاستیک نیست؛ ممکن است وسیله‌ای مانع بسته شدن کامل در شده باشد. محل رطوبت و زمان شکل گرفتن آن را به تعمیرکار نشان دهید."],["لولا مهم‌تر از ظاهر واشر","اگر در کج قرار گرفته باشد، حتی لاستیک سالم هم نمی‌تواند تماس یکنواخت با کابین برقرار کند. نخست وضعیت لولا، پایه و گیر نکردن کشوها بررسی شود. تغییر شکل دادن واشر با حرارت مستقیم ممکن است آسیب بیشتری به آن برساند."],["چرا واشر جدید گاهی کار نمی‌کند؟","نصب لاستیک با ابعاد یا کد نامناسب می‌تواند همچنان فاصله‌ای برای ورود هوا باقی بگذارد. انتخاب قطعه باید طبق مدل دقیق باشد. بعد از نصب نیز تماس تمام لبه‌ها و بسته شدن در باید آزمون شود، نه فقط ظاهر قطعه."],["نگهداری دور در در چمستان","در محیط‌هایی با رطوبت بالاتر، بازماندن مداوم در باعث ورود بخار آب به کابین می‌شود. شست‌وشوی ملایم لبه لاستیک و اطمینان از بسته شدن کامل در می‌تواند به کاهش برفک کمک کند. برای آب‌بندی واقعی باید علت دقیق مشخص شود."]],"electrosteel":[["دوقلو بودن همیشه به معنی مدار مشترک نیست","در برخی مجموعه‌های دوقلوی الکترواستیل، کابین یخچال و فریزر عملکرد مستقل دارند. اگر یکی گرم شده، تعمیر هر دو بدون دلیل فنی درست نیست. شماره مدل هر قسمت را جداگانه ثبت کنید تا مسیر بررسی به کابین درست محدود شود."],["عیب‌یابی هر کابین از دمای خودش","برای گزارش افت سرما، دمای واقعی فریزر و یخچال را مستقل اندازه‌گیری کنید. یک واحد می‌تواند درست کار کند در حالی که دیگری با عیب فن، سنسور یا مدار روبه‌رو باشد. مشابه بودن ظاهر دو کابین جای آزمایش جداگانه را نمی‌گیرد."],["تأمین قطعه متناسب با مدل","فریزر دوقلو ممکن است به قطعه‌ای متفاوت از واحد یخچال نیاز داشته باشد. انتخاب فن یا برد صرفاً براساس نام برند به خرید اشتباه منجر می‌شود. تعمیرکار باید کد مدل همان واحد معیوب را با قطعه جایگزین تطبیق دهد."],["فضای نصب بین دو بدنه","اگر مجموعه دوقلو بسیار نزدیک دیوار یا کابینت نصب شده، خروج هوای گرم از اطراف آن دشوارتر می‌شود. فاصله پیشنهادی سازنده و مسیر عبور هوا را برای هر دو دستگاه بررسی کنید. به لوله‌ها و اتصالات برقی پشت دستگاه فشار وارد نکنید."]],"depoint":[["یخ‌زدگی نزدیک خروجی هوا","گاهی در دیپوینت مواد درست روبه‌روی دریچه هوای سرد یخ می‌زنند، در حالی که بخش‌های دورتر چندان خنک نیستند. این الگوی موضعی را باید از خرابی عمومی سیستم سرمایش جدا کرد. محل هر دو نشانه را یادداشت کنید."],["اثر چیدمان طبقات بر دما","وقتی بسته بزرگ مسیر هوا را می‌پوشاند، سرمایش میان طبقات یکسان توزیع نمی‌شود. پیش از نتیجه‌گیری درباره سنسور، چیدمان را مطابق توصیه سازنده اصلاح کنید. برای اندازه‌گیری، دما را بعد از زمان کافی برای پایداری ثبت کنید."],["تست دریچه و حسگر به ترتیب منطقی","ادامه اختلاف دما می‌تواند بررسی عملکرد فن، دریچه و سنسور را ضروری کند. آزمایش باید مطابق مدل انجام شود. سفارش برد کنترل بدون مشخص شدن اینکه جریان هوا درست توزیع می‌شود یا نه ممکن است هزینه غیرضروری ایجاد کند."],["چطور مشکل را دقیق گزارش کنیم؟","به جای گفتن اینکه کل یخچال خراب است، مشخص کنید کدام طبقه بیش از حد سرد و کدام قسمت گرم است. زمان مشاهده نشانه و وضعیت تنظیم دما را هم ثبت کنید. این گزارش برای تشخیص جریان هوا بسیار مفیدتر است."]],"himalaya":[["صدا از داخل فریزر است یا پشت بدنه؟","در هیمالیا صدای تق‌تق ممکن است از ظرف لرزان، تماس بدنه با کابینت یا بخش داخلی فن باشد. بهتر است ابتدا محل تقریبی صدا و لحظه وقوع آن را مشخص کنید. شناسایی منبع قبل از سفارش قطعه احتمال هزینه اضافه را کم می‌کند."],["وقتی باز کردن در صدا را تغییر می‌دهد","در بعضی مدل‌ها کارکرد فن با وضعیت در تغییر می‌کند. اگر صدا هنگام باز شدن در کم یا زیاد می‌شود، این رفتار را ثبت کنید، اما از روی آن تشخیص قطعی ندهید. بررسی عملکرد فن و وجود یخ پنهان به تجهیزات سرویس نیاز دارد."],["لرزش مکانیکی با عیب سرمایش یکی نیست","تماس بدنه با سطح اطراف یا تراز نبودن پایه‌ها می‌تواند صدای لرزشی بسازد، در حالی که سرمایش طبیعی باشد. در مقابل، صدای فن همراه با افت سرما مسیر دیگری از بررسی را مطرح می‌کند. هر دو علامت را جداگانه توضیح دهید."],["ضبط صدا برای مراجعه تکنسین","یک ویدیوی کوتاه هنگام شروع و توقف دستگاه می‌تواند به تعمیرکار کمک کند. باز کردن پنل در حالت برق‌دار برای پیدا کردن صدا خطرناک است. اگر صدای شدید یا بوی سوختگی وجود دارد، استفاده از دستگاه را متوقف کنید."]],"beko":[["برفک دور در همیشه از لاستیک نیست","در فریزر بکو اگر نزدیک لبه در برفک دیده می‌شود، نفوذ هوای مرطوب یکی از احتمال‌هاست. گاهی سبد یا بسته‌ای بیرون زده و مانع بسته شدن کامل در می‌شود. پیش از خرید واشر، جایگیری وسایل را بررسی کنید."],["چگونه وضعیت در را مشاهده کنیم؟","آسیب قابل مشاهده واشر، گیر کردن کشو و تراز نبودن پایه‌ها را بدون جدا کردن قطعات بررسی کنید. خم کردن فلز لولا یا حرارت دادن لاستیک راهکار مناسب خانگی نیست. اگر در کاملاً چفت نمی‌شود، بررسی تخصصی لازم است."],["مشخصات لاستیک جایگزین","شباهت ظاهری واشر با قطعه اصلی کافی نیست. اندازه و طراحی شیار اتصال باید با شماره مدل دستگاه تطبیق داشته باشد. تعمیرکار پس از نصب باید بسته شدن یکنواخت در را کنترل کند تا هوای گرم دوباره وارد کابین نشود."],["چرا رطوبت دوباره برمی‌گردد؟","اگر مانع بسته شدن در یا ناترازی لولا برطرف نشده باشد، حتی نصب واشر تازه هم ممکن است نتیجه کامل ندهد. بعد از چیدن مواد غذایی، بسته شدن در را کنترل کنید و لبه لاستیک را با دستمال نرم پاک کنید."]],"hisense":[["پیش از ریست از خطا عکس بگیرید","نمایش یک نماد یا کد در یخچال هایسنس باید همراه با شماره مدل تفسیر شود. بازنشانی فوری می‌تواند پیام را موقتاً حذف کند و اطلاعات عیب را از بین ببرد. عکس نمایشگر و زمان وقوع خطا را برای تعمیرکار نگه دارید."],["فرق مشکل حسگر با تغییر شرایط محیط","گاهی پس از قطعی برق یا باز ماندن طولانی در، رفتار نمایشگر عوض می‌شود. پیش از سفارش سنسور، دمای واقعی کابین، وضعیت در و مدت بازگشت به حالت پایدار را ثبت کنید. تمام هشدارها به معنی خرابی برد نیستند."],["خطای مشابه در دو مدل متفاوت","یک کد روی دو سری محصول ممکن است تعریف یکسان نداشته باشد. اگر راهنمای اینترنتی متعلق به شماره مدل دیگری است، آن را مبنای تعویض قطعه قرار ندهید. تکنسین باید دفترچه سرویس مرتبط با دستگاه موجود را بررسی کند."],["کارهای خطرناک روی برد کنترل","اتصال کوتاه سنسور یا دستکاری سیم‌ها برای حذف خطا می‌تواند هم تشخیص را دشوار کند و هم به مدار آسیب بزند. بررسی‌های برقی را به فرد متخصص بسپارید. کاربر می‌تواند بدون باز کردن قطعات، علائم و زمان بروز را مستند کند."]],"hitachi":[["هر محفظه الزاماً تنظیم یکسان ندارد","در برخی یخچال‌های چندمحفظه‌ای هیتاچی دمای قسمت سبزیجات با بخش اصلی تفاوت دارد. قبل از تشخیص خرابی، عملکرد طراحی‌شده هر محفظه و تنظیمات انتخاب‌شده را از راهنمای همان مدل بررسی کنید."],["نقش دریچه و قرارگیری بسته‌ها","قرار دادن ظرف بزرگ کنار خروجی هوا می‌تواند سرمایش یک طبقه را تغییر دهد. اگر یک محفظه گرم و بخش دیگر سرد است، ابتدا چیدمان مواد و وضعیت بسته شدن درها را بررسی کنید. تغییرات را در طول زمان یادداشت کنید."],["چرا سنسورهای مدل‌ها یکی نیستند؟","تعداد و موقعیت سنسورها و مسیر گردش هوا در سری‌های مختلف می‌تواند متفاوت باشد. آزمون باید براساس شماره مدل انجام شود. سفارش سنسور صرفاً با اتکا به نام هیتاچی خطر انتخاب قطعه نامناسب دارد."],["اندازه‌گیری هر بخش جداگانه","برای گزارش دقیق عیب، وضعیت دمای طبقه اصلی، محفظه سبزیجات و فریزر را مستقل یادداشت کنید. آیا گرم شدن پس از خرید روزانه رخ داده یا همیشه ادامه دارد؟ پاسخ این سؤال به محدود کردن مسیر عیب‌یابی کمک می‌کند."]],"kenwood":[["گرمای دیواره و دفع حرارت","در برخی مدل‌های کنوود، بدنه هنگام کار سیستم سرمایش گرما پس می‌دهد. صرف داغ بودن یک سطح به معنی کمبود مبرد نیست؛ باید دید دمای داخل به مقدار مناسب می‌رسد یا نه. این دو مشاهده را جدا ثبت کنید."],["آشپزخانه کوچک و تهویه نامناسب","اگر یخچال بین دو کابینت یا کنار اجاق قرار گرفته باشد، محیط گرم می‌تواند کارکرد موتور را طولانی‌تر کند. فاصله مناسب با دیوار را از دفترچه تعیین کنید و از دستکاری لوله‌ها یا اتصالات داغ پشت دستگاه خودداری کنید."],["وقتی گرم بودن بدنه با افت سرما همراه است","در این حالت بررسی فن و تبادل گرما، تنظیمات و مدار سرمایش اهمیت بیشتری دارد. برای نتیجه‌گیری درباره نشتی، آزمایش تخصصی لازم است. پیشنهاد شارژ مبرد بدون تشخیص علت نباید تنها گزینه تعمیر باشد."],["ثبت شرایط نصب برای تکنسین","عکس محل نصب، فاصله پشت دستگاه و دمای نسبی محفظه می‌تواند از تکرار بازدید جلوگیری کند. اگر دستگاه به‌تازگی جابه‌جا شده، زمان آن را اطلاع دهید. تعمیر موفق با شناسایی علت واقعی آغاز می‌شود."]],"eastcool":[["محدودیت فضا در یخچال کوچک","در برخی یخچال‌های کوچک ایستکول، جای اندک کابین باعث می‌شود بسته‌ها نزدیک سطح سردکننده قرار بگیرند. یخ زدن بعضی خوراکی‌ها همیشه نشانه خرابی ترموستات نیست؛ چیدمان و نوع طراحی سرمایش نیز اثر دارد."],["بارگذاری غذای گرم و زمان پایدارشدن","وقتی حجم زیادی مواد گرم در کابین کوچک می‌گذارید، رسیدن دما به نقطه مطلوب فوری نیست. قبل از تشخیص افت سرمایش، شرایط عادی دستگاه و فرصت لازم را در نظر بگیرید. مسیر گردش هوای داخل را مسدود نکنید."],["شناخت ترموستات همان مدل","در مدل‌های ساده‌تر ایستکول ممکن است شیوه کنترل دما با یخچال دیجیتال نوفراست متفاوت باشد. تست قطعات راه‌انداز و ترموستات به شناخت ساختار دستگاه نیاز دارد. توصیه تعویض برد برای مدلی که چنین بخشی ندارد اشتباه است."],["انتخاب محل نصب برای دستگاه جمع‌وجور","یخچال کوچک را نباید به دلیل ابعاد کم کاملاً به دیوار چسباند. فاصله توصیه‌شده و مسیر تهویه را از دفترچه همان مدل بررسی کنید. هوای گرم اطراف دستگاه ممکن است عملکرد آن را تحت تأثیر قرار دهد."]],"pars":[["سیکل روشن شدن موتور چه زمانی طبیعی است؟","در یخچال پارس توقف و شروع دوره‌ای کمپرسور می‌تواند بخشی از کنترل دما باشد. مسئله زمانی مهم است که دمای واقعی کابین مناسب نباشد یا دستگاه به شکل غیرعادی خاموش بماند. زمان چرخه‌ها را در شرایط عادی ثبت کنید."],["تنظیم ترموستات و شرایط بارگذاری","اگر سرمایش کافی نیست، وضعیت تنظیم دما و بسته شدن در را بررسی کنید. چیدن مواد گرم یا باز و بسته کردن مداوم در می‌تواند زمان کارکرد را تغییر دهد. تغییر شرایط استفاده را از خرابی قطعات تفکیک کنید."],["خطر دور زدن مدار کنترل","برای آزمودن ترموستات نباید سیم‌ها را به هم وصل کرد یا رله را خودسرانه دور زد. این کار هم خطر برق دارد و هم می‌تواند به کمپرسور آسیب بزند. بررسی تخصصی با ابزار و دستورالعمل مدل انجام شود."],["اطلاعات مفید درباره قطع برق","اگر نوسان برق یا قطعی‌های مکرر وجود داشته، زمان آن را به تعمیرکار اطلاع دهید. صدای راه‌اندازی پس از برگشت برق ممکن است با سیکل معمول فرق داشته باشد. تشخیص قطعی قطعه معیوب بدون آزمون درست نیست."]]}''')
NAMES={x[0]:x[1] for x in PROFILES}
BASE="https://alotamiratchi.ir/"
errors=[]
saved=[]
texts=[]
for idx,(key,name,focus,scenario,inspect,expert,prevention,question,answer) in enumerate(PROFILES):
    slug=key+"-refrigerator-repair-chamestan"
    try:
        article=tool("find_content",{"type":"brand_article","slug":slug}).get("record")
        if not article:raise ValueError("Brand record absent")
        old=article.get("content") or ""
        if int(article.get("brand_id") or 0)!=5 or int(article.get("status") or 0)!=1 or not article.get("img"):
            raise RuntimeError("Wrong category / not published / no image")
        links=RELATIONS[key]
        url1=BASE+links[0]+"-refrigerator-repair-chamestan/"+str(506+INDEX[links[0]])
        url2=BASE+links[1]+"-refrigerator-repair-chamestan/"+str(506+INDEX[links[1]])
        intro=("در محله‌ها و روستاهای اطراف چمستان، دستگاه "+name+" ممکن است با نشانه‌ای مواجه شود که در نگاه اول به خرابی بزرگی شبیه است. این راهنما درباره "+focus+" است و روش تصمیم‌گیری بدون تشخیص عجولانه را توضیح می‌دهد. ارتباطی با نمایندگی رسمی سازنده ادعا نمی‌شود." if idx%2 else
          "اگر یخچال "+name+" شما در چمستان خوب کار نمی‌کند، لازم نیست از ابتدا سراغ تعویض موتور یا برد بروید. برای مسئله "+focus+" ابتدا باید نشانه مشاهده‌شده را از برداشت اولیه جدا کرد. این صفحه صرفاً راهنمای مستقل تعمیر است و نمایندگی رسمی برند نیست.")
        # Brand-specific structure; different positions for safety, symptoms, and diagnosis.
        c=[
            ("مسئله اصلی؛ "+focus,scenario),
            ("آنچه در خانه می‌توان مشاهده کرد",inspect),
            ("روش تصمیم‌گیری تکنسین برای این عیب",expert),
            ("پیشگیری متناسب با دستگاه "+name,prevention),
            (question,answer)]
        common=EXTRAS[key]
        order=([0,1,5,2,6,3,7,4,8] if idx%3==0 else
               [0,5,1,6,2,7,3,4,8] if idx%3==1 else
               [5,0,1,6,3,7,2,8,4])
        all_sections=c+common
        bits=["<p>"+intro+"</p>"]
        for slot,section_idx in enumerate(order):
            heading,paragraph=all_sections[section_idx]
            bits.append(("<h3>" if section_idx==4 else "<h2>")+html.escape(heading)+
                        ("</h3>" if section_idx==4 else "</h2>"))
            bits.append("<p>"+paragraph+"</p>")
            if slot==1:
                bits.append('<p>اگر نشانه‌ها به هم شبیه شده‌اند، <a href="'+url1+'">راهنمای یخچال '+NAMES[links[0]]+' در چمستان</a> را برای مقایسه الگوی خرابی بخوانید؛ نتیجه مدل دیگر را مستقیماً به دستگاه خود تعمیم ندهید.</p>')
            if slot==4:
                bits.append('<p>توضیح بیشتری درباره تفاوت عیب‌های نزدیک در <a href="'+url2+'">مقاله یخچال '+NAMES[links[1]]+' در چمستان</a> وجود دارد. انتخاب قطعه باید برای مدل فعلی انجام شود.</p>')
            if slot==6:
                bits.append('<p>برای خدمات عمومی همین شهر، <a href="https://alotamiratchi.ir/refrigerator-repair-in-chamestan">راهنمای تعمیر یخچال چمستان</a> را بررسی کنید و شرایط پذیرش خدمات را از ارائه‌دهنده بپرسید.</p>')
        bits.append('<h2>نکته آخر برای '+name+'</h2><p>ثبت نشانه، جلوگیری از دستکاری مدار و درخواست آزمایش متناسب با شماره مدل از تکرار هزینه تعمیر جلوگیری می‌کند. مطالب <a href="https://tekanino.ir/refrigerator">تعمیر یخچال در تکانی‌نو</a> نیز برای آشنایی با مسائل کلی مفید است؛ تشخیص نهایی به وضعیت همین دستگاه بستگی دارد.</p>')
        content="\n".join(bits)
        # Skip only a fully rewritten record; leave titles, slug, status, description, image untouched.
        if old!=content:
            tool("update_content",{"type":"brand_article","id":int(article["id"]),
                 "fields":{"content":content},"confirm_public":True})
        fresh=tool("get_content",{"type":"brand_article","id":int(article["id"])})["record"]
        for prop in ("id","slug","title","img","brand_id","status"):
            if str(fresh.get(prop))!=str(article.get(prop)):
                raise RuntimeError("Unexpected mutation: "+prop)
        if fresh["content"]!=content or len(re.findall(r"<a href=",content))<4:
            raise RuntimeError("Content readback or contextual links failed")
        saved.append((key,int(article["id"])))
        clean=" ".join(re.sub(r"<[^>]*>"," ",content).split())
        for brand in NAMES.values():clean=clean.replace(brand,"BRAND")
        texts.append((key,clean))
        print("CHAMESTAN_UNIQUE_REWRITE_VERIFIED",key,article["id"],len(clean.split()),flush=True)
    except Exception as e:
        errors.append((key,type(e).__name__,str(e)[:220]))
        print("CHAMESTAN_REWRITE_ERROR",key,type(e).__name__,str(e)[:220],flush=True)
scores=[]
for i,(ka,ta) in enumerate(texts):
    for kb,tb in texts[i+1:]:
        scores.append((round(SequenceMatcher(None,ta,tb,autojunk=False).ratio(),3),ka,kb))
scores.sort(reverse=True)
print("CHAMESTAN_UNIQUE_REWRITE_RESULT",json.dumps({"verified":len(saved),"errors":errors,"highest_similarities":scores[:5]},ensure_ascii=False),flush=True)
if errors or len(saved)!=15:raise SystemExit(2)
